-- Put the shared texts back (D-77). / Devuelve los textos compartidos (D-77).
do
	local S, src = IL.DB.sourceStrings, IL.DB.sources
	for id, v in pairs(src) do if type(v) == "number" then src[id] = S[v] end end
	IL.DB.sourceStrings = nil
end
